import { getConfigManager } from '../ConfigManager';
import type {
  ChangeRequest,
  CommentChangeItem,
} from '../../types/change-request-types';

const accounts = new WeakMap<CommentChangeItem, string>();

export const bindProfileAccount = (
  request: ChangeRequest,
  accountId: string,
): void => {
  for (const change of request.changes)
    if (
      change.kind === 'comment' &&
      (change.profileTrace?.status === 'selected' ||
        change.profileTrace?.suppliedReferences?.length)
    )
      accounts.set(change, accountId);
};

export const assertProfileAccount = (change: CommentChangeItem): void => {
  const accountId = accounts.get(change);
  if (!accountId) return;
  const config = getConfigManager();
  if (!config.isAuthenticated() || config.getUserId() !== accountId)
    throw new Error(
      'Profile account changed before reference delivery; retry the request',
    );
};
